import {StoryGame,ROOMS,ITEMS,ENDINGS} from './story-engine.js';
import {freshSeed,seededRandom,shuffle,pick,worldLook,WEATHER,hash} from './world.js';
const PLOTS=[{title:'The rooftop rescue',event:'a rooftop benefit',venue:'SKYLINE SOCIAL',need:'The headliner vanished with the only copy of the anthem.'},{title:'Pirate-radio romance',event:'a midnight radio takeover',venue:'RADIO ROOFTOP',need:'The station has six minutes of dead air and a DJ with eighteen excuses.'},{title:'The disco reunion',event:'a reunion for a club nobody admits attending',venue:'LAST DANCE',need:'The reunion playlist is trapped on an unfinished record.'},{title:'The moonlight parade',event:'a surprise street-festival finale',venue:'MOONLIGHT PARADE',need:'The parade float has lights, glitter, and absolutely no music.'}];
const CAST={promoter:['Roxy','Moxie','Cleo','Juno','Velvet','Ziggy'],dj:['Vinyl','Tempo','Echo','Orbit','Riff','Cassette'],barista:['Bean','Miso','Coco','Biscuit','Maple','Pepper'],guard:['Brick','Atlas','Tank','Duke','Boulder','Rook'],partner:['Nova','Indie','Luna','Sage','Clover','Jazz']};
const PAD_WORDS=['MOON','BASS','BARK','GLOW','WAVE','STAR'];
const flags=['flyer','token','awake','styled','password','mixed','pass','nova','kind','brag','favor'];
const inventory=[...Object.keys(ITEMS),'souvenir'];
const personality={curious:'Ask about the weirdest thing they have discovered.',playful:'A silly joke lands better than a polished speech.',grounded:'An honest answer beats a grand entrance.'};
export function episodeFor(seed){const random=seededRandom(seed),cast=Object.fromEntries(Object.entries(CAST).map(([role,list])=>[role,pick(random,list)])),plot=pick(random,PLOTS),barRoom=random()<.5?'diner':'shop',djRoom=barRoom==='diner'?'shop':'diner',tokenRoom=pick(random,['block','club',barRoom]),mood=pick(random,Object.keys(personality)),recipe=shuffle(random,PAD_WORDS).slice(0,3),password=pick(random,PAD_WORDS),favor=pick(random,['red','blue','gold']);
 const rooms={...ROOMS,block:{...ROOMS.block,name:pick(random,['Neon Strip','Lantern Lane','Comet Plaza','Velvet Walk'])},diner:{...ROOMS.diner,name:barRoom==='diner'?pick(random,['The Last Bite','Moonbean Café','The 2AM Club']):pick(random,['Basement Frequencies','The Listening Room','Static Kitchen'])},shop:{...ROOMS.shop,name:barRoom==='shop'?pick(random,['Coffee & Cassettes','The Vinyl Café','Sleepless Records']):pick(random,['Off the Record','Echo Exchange','Electric Attic'])},club:{...ROOMS.club,name:pick(random,['The Velvet Rope','The Lucky Lift','Gold Door'])},roof:{...ROOMS.roof,name:plot.venue}};
 rooms[barRoom]={...rooms[barRoom],label:'COFFEE AFTER MIDNIGHT'};rooms[djRoom]={...rooms[djRoom],label:'FREQUENCIES AFTER DARK'};return {cast,plot,barRoom,djRoom,tokenRoom,mood,recipe,password,favor,rooms,look:worldLook(seed)};
}
export function validStorySave(s){if(s?.version===1)return StoryGame.valid(s);if(s?.version!==2||!Number.isInteger(s.episodeSeed)||s.episodeSeed<1||s.episodeSeed>0xffffffff)return false;const e=episodeFor(s.episodeSeed);return Object.hasOwn(ROOMS,s.room)&&Array.isArray(s.inventory)&&s.inventory.length<=8&&new Set(s.inventory).size===s.inventory.length&&s.inventory.every(i=>inventory.includes(i))&&s.flags&&typeof s.flags==='object'&&!Array.isArray(s.flags)&&Object.entries(s.flags).every(([k,v])=>flags.includes(k)&&typeof v==='boolean')&&Array.isArray(s.mix)&&s.mix.length<=3&&s.mix.every((v,i)=>v===e.recipe[i])&&Number.isSafeInteger(s.moves)&&s.moves>=0&&s.moves<1e7&&[null,'mixer','password','nova','favor'].includes(s.topic)&&(s.ending===null||Object.hasOwn(ENDINGS,s.ending))&&typeof s.text==='string'&&s.text.length<3000&&typeof s.speaker==='string'&&s.speaker.length<100;}
export function createStory(saved=null,seed=freshSeed()){return saved?.version===1&&StoryGame.valid(saved)?new StoryGame(saved):new LivingStoryGame(saved,seed);}
export class LivingStoryGame {
 constructor(saved=null,seed=freshSeed()){const s=saved?.version===2&&validStorySave(saved)?saved:null;this.episodeSeed=s?.episodeSeed||seed||1;this.episode=episodeFor(this.episodeSeed);this.room='block';this.inventory=['comb'];this.flags={};this.mix=[];this.moves=0;this.topic=null;this.ending=null;this.notice='';this.speaker='THE NARRATOR';this.text=`Midnight. ${this.episode.plot.need} ${this.episode.cast.promoter} needs a DAWG with confidence, pockets, and a flexible relationship with dignity.`;if(s)for(const k of ['room','inventory','flags','mix','moves','topic','ending','text','speaker'])this[k]=JSON.parse(JSON.stringify(s[k]));}
 has(id){return this.inventory.includes(id);}give(id){if(!this.has(id))this.inventory.push(id);}take(id){this.inventory=this.inventory.filter(i=>i!==id);}
 roomInfo(id=this.room){return this.episode.rooms[id];}
 item(id){if(id==='flyer')return {...ITEMS.flyer,description:`${this.episode.plot.venue}. Password: ${this.episode.password}. Soundcheck: ${this.episode.recipe.join(' → ')}. Lost badge: ${this.episode.favor.toUpperCase()}.`};if(id==='souvenir')return {name:'Crew pin',icon:'✧',description:'A tiny thank-you from the promoter. Sometimes the side quest is the part people remember.'};if(id==='coffee')return {...ITEMS.coffee,description:`Take this to DJ ${this.episode.cast.dj} at ${this.roomInfo(this.episode.djRoom).name}.`};return ITEMS[id];}
 say(text,speaker='THE NARRATOR'){this.text=text;this.speaker=speaker;}
 describe(){const e=this.episode,c=e.cast,w=WEATHER[(e.look.weather+Math.floor(this.moves/8))%5];if(this.room==='block')return `${w}. ${c.promoter} is trying to save ${e.plot.event}. ${e.plot.need} A flyer and a suspiciously decorative fountain compete for your attention.`;if(this.room===e.barRoom)return `${c.barista} polishes a cup while a customer pitches a startup that is definitely just a sandwich. Coffee costs one token. Your dignity remains complimentary.`;if(this.room===e.djRoom)return this.flags.awake?`DJ ${c.dj} is awake. Three soundcheck pads blink beside an unfinished record. The flyers around town contain the code.`:`DJ ${c.dj} fell asleep at the desk. Each snore adds a kick drum. This might be a new genre, but it will not save tonight's show.`;if(this.room==='club')return `${c.guard} checks the guest list. The mirror has no filter and no loyalty. A password, a finished demo, and a brushed coat should get you through.`;return `${c.partner} watches the city from the rooftop. ${personality[e.mood]} Below, ${e.plot.event} is gathering a crowd.`;}
 go(room){if(this.ending||!Object.hasOwn(ROOMS,room))return false;if(room==='roof'&&!this.flags.pass){this.say(`The lift needs a wristband. Talk to ${this.episode.cast.guard} at ${this.roomInfo('club').name}.`);return false;}this.room=room;this.moves++;this.topic=null;this.notice='';this.say(this.describe());return true;}
 use(item){if(this.ending||!this.has(item))return false;this.moves++;this.topic=null;this.notice='';const e=this.episode;
  if(item==='comb'&&this.room==='club'){this.flags.styled=true;this.say(`One flick of the comb. ${e.cast.guard} nods. “A dramatic improvement. Before, you looked like a rug with a business plan.”`,e.cast.guard.toUpperCase());this.notice='STYLE CHECK PASSED';}
  else if(item==='token'&&this.room===e.barRoom){this.take('token');this.give('coffee');this.say(`“One double espresso. Do not let it make decisions for you.” ${e.cast.barista} points toward ${this.roomInfo(e.djRoom).name}.`,e.cast.barista.toUpperCase());}
  else if(item==='coffee'&&this.room===e.djRoom){this.take('coffee');this.give('vinyl');this.flags.awake=true;this.say(`“I was not asleep. I was listening internally.” ${e.cast.dj} hands you a record. “Use the mixing desk. The flyer has today's soundcheck.”`,'DJ '+e.cast.dj.toUpperCase());}
  else if(item==='vinyl'&&this.room===e.djRoom){this.topic='mixer';this.say(`The pads are ready. Today's order is ${this.has('flyer')?e.recipe.join(' → '):'printed on the flyer'}.`,'SOUNDCHECK');}
  else if(item==='demo'&&this.room==='roof')this.end('headliner');else if(item==='pass')this.go('roof');else this.say(this.item(item).description,'YOUR POCKETS');return true;
 }
 hint(){const e=this.episode;if(!this.flags.token&&!this.flags.awake&&!this.has('coffee'))return `Look for something glinting at ${this.roomInfo(e.tokenRoom).name}. The token changes hiding places each episode.`;if(this.has('token'))return `Use the token at ${this.roomInfo(e.barRoom).name}. ${e.cast.barista} makes the coffee.`;if(this.has('coffee'))return `Use coffee at ${this.roomInfo(e.djRoom).name} to wake DJ ${e.cast.dj}.`;if(!this.flags.mixed)return `Use the record at ${this.roomInfo(e.djRoom).name}. Soundcheck: ${e.recipe.join(' → ')}.`;if(!this.flags.styled)return 'Use your comb at the club mirror.';if(!this.flags.password)return `Tell the guard ${e.password}. The flyer has the clue.`;if(!this.flags.pass)return `Talk to ${e.cast.guard} with the finished demo and your new look.`;if(!this.flags.kind)return `On the roof: ${personality[e.mood]} You can recover from a bad first impression.`;return `Try one of three endings. An optional lost-badge favor on the Strip adds a personal twist.`;}
 get result(){if(!this.ending)return null;const e=this.episode,c=e.cast,base=ENDINGS[this.ending],titles={headliner:['THE ROOFTOP LEGEND','SIGNAL RESTORED','DISCO REDEMPTION','PARADE OF ONE'],connection:['BREAKFAST FOR TWO','THE QUIET ENCORE','A BETTER FIRST IMPRESSION','ONE MORE COFFEE'],flop:['ACCIDENTAL ICON','THE BARK HEARD ROUND TOWN','GLORIOUSLY UNQUALIFIED','LOCAL MEME, GLOBAL AMBITION']};let text=this.ending==='headliner'?`DJ ${c.dj}'s anthem lands. ${e.plot.event} erupts. ${c.promoter} sends a voice note that is mostly screaming. ${c.guard} pretends not to dance.`:this.ending==='connection'?`${c.partner} asks about breakfast. You forget the speech you rehearsed and answer honestly. The city gets its show; you get a reason to stay past sunrise.`:`You improvise a ballad about a parking meter. ${c.partner} laughs first. The crowd joins in. By sunrise, ${c.promoter} has booked you as “deliberate comedy.” Nobody corrects the flyer.`;const snack=pick(seededRandom(this.episodeSeed+440),['pancakes with far too much syrup','a heroic plate of hash browns','two coffees and a shared croissant','breakfast noodles','midnight waffles','the last cinnamon bun']);text+=` At ${this.roomInfo(e.barRoom).name}, ${c.barista} keeps a table for ${snack}. The speakers still hum ${e.recipe.join(' / ')}.`;text+=this.flags.favor?` Your crew pin catches the light. Someone remembers the small kindness before the big entrance.`:` Somewhere downstairs, a lost badge is still waiting for its own hero.`;return {title:titles[this.ending][Math.floor(hash(this.episodeSeed,900)*4)],text,score:base.score+(this.flags.favor?150:0)};}
 end(id){if(!Object.hasOwn(ENDINGS,id)||this.ending)return;this.ending=id;this.topic=null;this.say(this.result.text,this.result.title);this.notice='EPISODE COMPLETE · '+this.moves+' MOVES';}
 actions(){if(this.ending)return [];const e=this.episode,c=e.cast,a=(id,label,detail,run)=>({id,label,detail,run});
  if(this.topic==='mixer')return shuffle(seededRandom(this.episodeSeed+19),e.recipe).map(t=>a('mix-'+t,t,'Follow the flyer, not the button order.',()=>{if(t===e.recipe[this.mix.length]){this.mix.push(t);if(this.mix.length===3){this.flags.mixed=true;this.take('vinyl');this.give('demo');this.topic=null;this.say(`The bass lands. ${c.dj} grins. “Take this to ${c.guard}. And spell my name right.”`,'DJ '+c.dj.toUpperCase());this.notice='DEMO COMPLETE';}else this.say(this.mix.join(' → ')+'. What comes next?','SOUNDCHECK');}else{this.mix=[];this.say('That sounded like a printer arguing with a goose. Try the order on the flyer.','SOUNDCHECK');}}));
  if(this.topic==='password')return shuffle(seededRandom(this.episodeSeed+20),[e.password,...PAD_WORDS.filter(w=>w!==e.password).slice(0,2)]).map(word=>a('password-'+word,'“'+word+'.”','The flyer knows.',()=>{this.topic=null;if(word===e.password){this.flags.password=true;this.say('“Correct. Now show me style and a finished demo.”',c.guard.toUpperCase());}else this.say('“That is not today’s password. Try reading the flyer. Radical concept.”',c.guard.toUpperCase());}));
  if(this.topic==='nova')return [['curious','Ask about their strangest discovery'],['playful','Make a ridiculous observation'],['grounded','Admit you were nervous']].map(([m,label])=>a('connect-'+m,label,personality[e.mood],()=>{this.flags.nova=true;this.topic=null;if(m===e.mood){this.flags.kind=true;this.say(`“Finally, somebody speaking my language.” ${c.partner} makes room beside them. The conversation stops feeling like an audition.`,c.partner.toUpperCase());}else{this.flags.brag=true;this.say(`“You can relax. Try that again without performing.” ${personality[e.mood]}`,c.partner.toUpperCase());}}));
  if(this.topic==='favor')return ['red','blue','gold'].map(color=>a('badge-'+color,'Return the '+color+' badge','The party flyer describes the missing badge.',()=>{this.topic=null;if(color===e.favor){this.flags.favor=true;this.give('souvenir');this.say(`${c.promoter} laughs. “That's mine. You saved the small disaster too.” You receive a crew pin.`,c.promoter.toUpperCase());}else this.say('Wrong badge. A confused delivery driver thanks you anyway. The right color is on the flyer.');}));
  let actions=[];
  if(this.room==='block')actions=[a('poster','Read tonight’s flyer','Passwords and soundchecks change every episode.',()=>{this.flags.flyer=true;this.give('flyer');this.say(this.item('flyer').description,'THE FLYER');}),a('promoter','Talk to '+c.promoter,e.plot.title,()=>this.say(`${e.plot.need} Find a token at ${this.roomInfo(e.tokenRoom).name}, buy coffee at ${this.roomInfo(e.barRoom).name}, and wake ${c.dj} at ${this.roomInfo(e.djRoom).name}.`,c.promoter.toUpperCase())),a('favor',this.flags.favor?'Check your crew pin':'Help find the missing badge','Optional favor · changes the ending epilogue.',()=>{if(this.flags.favor)this.say('The pin is yours. The good deed still counts even if nobody films it.');else{this.topic='favor';this.say('Three badges in lost property. Which one matches the flyer?');}})];
  if(this.room===e.barRoom)actions=[a('bean','Talk to '+c.barista,'A barista with excellent boundaries.',()=>this.say(this.has('token')?'“Use the token in your pockets. I trade in coffee, not networking opportunities.”':`“A token is hiding at ${this.roomInfo(e.tokenRoom).name}. My machine does not accept confidence.”`,c.barista.toUpperCase())),a('menu','Read the chalkboard','A different local special.',()=>this.say(pick(seededRandom(this.episodeSeed+this.moves),['ESPRESSO: one token. TERRIBLE IDEAS: apparently free.','Our decaf is just an inspiring speech near a hot cup.','Tonight’s special: a double espresso and one fewer excuse.','Please stop telling the croissants about your portfolio.']),'THE MENU'))];
  if(this.room===e.djRoom)actions=[a('vinyl','Talk to DJ '+c.dj,this.flags.awake?'Awake. Technically.':'Currently buffering.',()=>this.say(this.flags.awake?'“Use the record or the desk. The flyer has the soundcheck.”':'A snore triggers the bass drum. Coffee should fix either the DJ or the genre.','DJ '+c.dj.toUpperCase())),a('desk','Use the mixing desk','A fresh sequence for this episode.',()=>{if(!this.flags.awake)this.say('The DJ is asleep on the power switch. Coffee first.');else if(this.flags.mixed)this.say('The demo is done. More bass is not always more wisdom.');else{this.topic='mixer';this.mix=[];this.say('Three pads, in the order on the flyer.','SOUNDCHECK');}})];
  if(this.room==='club')actions=[a('mirror','Check the mirror','Use your comb here.',()=>this.say(this.flags.styled?'Ready for your entrance. Maybe walk, though.':'Your hair looks like it has its own unfinished side quests.')),a('brick','Talk to '+c.guard,'Password, style, finished demo.',()=>{if(!this.flags.password){this.topic='password';this.say('“Tonight’s password?”',c.guard.toUpperCase());}else if(!this.flags.styled)this.say('“Comb. Mirror. You can solve this.”',c.guard.toUpperCase());else if(!this.flags.mixed)this.say('“Bring the finished demo.”',c.guard.toUpperCase());else{this.flags.pass=true;this.give('pass');this.say('“You’re in. Please do not lick any expensive surfaces.”',c.guard.toUpperCase());}}),a('lift','Take the lift','The night is above you.',()=>this.go('roof'))];
  if(this.room==='roof')actions=[a('nova','Talk to '+c.partner,'Listen to their mood.',()=>{this.topic='nova';this.say(`${c.partner} smiles. ${personality[e.mood]}`,c.partner.toUpperCase());}),a('play','Play the finished demo','The whole city is listening.',()=>this.end('headliner')),a('mic','Risk the open mic','Confidence is not a soundcheck.',()=>this.end('flop')),...(this.flags.kind?[a('sunrise','Stay for sunrise','A quieter kind of victory.',()=>this.end('connection'))]:[])];
  if(this.room===e.tokenRoom&&!this.flags.token)actions.push(a('fountain','Investigate the glint','A token hiding in tonight’s scenery.',()=>{this.flags.token=true;this.give('token');this.say('A coffee token! You are now solvent in exactly one café.');this.notice='COFFEE TOKEN FOUND';}));
  return actions;
 }
 choose(id){const a=this.actions().find(a=>a.id===id);if(!a)return false;this.notice='';this.moves++;a.run();return true;}
 save(){return {version:2,episodeSeed:this.episodeSeed,room:this.room,inventory:[...this.inventory],flags:{...this.flags},mix:[...this.mix],moves:this.moves,topic:this.topic,ending:this.ending,text:this.text,speaker:this.speaker};}
}
